{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.ZOUK_SWIGGY_ADS_FACT_ITEMS AS select \'SWIGGY\' CHANNEL ,\'PRODUCT ADS\' AD_TYPE ,SAFE_CAST(TOTAL_CTR as FLOAT64) as CTR ,COALESCE( SAFE.PARSE_DATE(\'%d-%b-%Y\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%Y-%m-%d\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%d-%m-%y\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%m/%d/%Y\', TRIM(METRICS_DATE)) ) AS Date ,SAFE_CAST(0 as FLOAT64) as Views ,SAFE_CAST(TOTAL_CLICKS as FLOAT64) as Clicks ,Campaign_ID ,SAFE_CAST(TOTAL_IMPRESSIONS as FLOAT64) as Impressions ,ba.Product_Name ,Campaign_Name ,SAFE_CAST(TOTAL_ROI as FLOAT64) * SAFE_CAST(TOTAL_BUDGET_BURNT as FLOAT64) as ad_sales ,SAFE_CAST(TOTAL_BUDGET_BURNT as FLOAT64) as spend ,COALESCE(km.collection, bm.collection) AS Collection ,\'Manual\' AS Type from MapleMonk.ZOUK_S3_SWIGGY_INSTAMART_ADS ba left join ( select * from MapleMonk.ZOUK_swiggy qualify row_number() over(partition by lower(Product_Name) order by 1) = 1 )bm on lower(ba.Product_Name) = lower(bm.Product_Name) LEFT JOIN MapleMonk.Zouk_Quick_Commerce_Ads_mapping km ON LOWER(ba.Campaign_Name) LIKE CONCAT(\'%\', LOWER(km.keyword), \'%\') where METRICS_DATE <> \'\' AND COALESCE( SAFE.PARSE_DATE(\'%d-%b-%Y\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%Y-%m-%d\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%d-%m-%y\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%m/%d/%Y\', TRIM(METRICS_DATE)) ) <= \'2025-06-30\' UNION ALL SELECT \'SWIGGY\' AS Channel ,\'PRODUCT ADS\' AD_TYPE ,SAFE_CAST(TOTAL_CTR as FLOAT64) as CTR ,COALESCE( SAFE.PARSE_DATE(\'%Y-%m-%d\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%d-%m-%y\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%m/%d/%Y\', TRIM(METRICS_DATE)) ) AS Date ,SAFE_CAST(0 as FLOAT64) as Views ,SAFE_CAST(TOTAL_CLICKS as FLOAT64) as Clicks ,Campaign_ID ,SAFE_CAST(TOTAL_IMPRESSIONS as FLOAT64) as Impressions ,s.Product_Name ,Campaign_Name ,SAFE_CAST(TOTAL_ROI as FLOAT64) * SAFE_CAST(TOTAL_BUDGET_BURNT as FLOAT64) as ad_sales ,SAFE_CAST(TOTAL_BUDGET_BURNT as FLOAT64) as spend ,UPPER(COALESCE(km.collection, bm.collection)) AS Collection ,\'API\' AS Type from `MapleMonk.zouk_db_SwiggyInstamart_ads` s left join ( select * from MapleMonk.ZOUK_swiggy qualify row_number() over(partition by lower(Product_Name) order by 1) = 1 )bm on lower(s.Product_Name) = lower(bm.Product_Name) LEFT JOIN MapleMonk.Zouk_Quick_Commerce_Ads_mapping km ON LOWER(s.Campaign_Name) LIKE CONCAT(\'%\', LOWER(km.keyword), \'%\') where METRICS_DATE <> \'\' UNION ALL SELECT \'SWIGGY\' AS Channel ,\'PRODUCT ADS\' AD_TYPE ,SAFE_CAST(TOTAL_CTR as FLOAT64) as CTR ,COALESCE( SAFE.PARSE_DATE(\'%Y-%m-%d\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%d-%m-%y\', TRIM(METRICS_DATE)), SAFE.PARSE_DATE(\'%m/%d/%Y\', TRIM(METRICS_DATE)) ) AS Date ,SAFE_CAST(0 as FLOAT64) as Views ,SAFE_CAST(TOTAL_CLICKS as FLOAT64) as Clicks ,Campaign_ID ,SAFE_CAST(TOTAL_IMPRESSIONS as FLOAT64) as Impressions ,null as Product_Name ,Campaign_Name ,SAFE_CAST(TOTAL_ROI as FLOAT64) * SAFE_CAST(TOTAL_BUDGET_BURNT as FLOAT64) as ad_sales ,SAFE_CAST(TOTAL_BUDGET_BURNT as FLOAT64) as spend ,UPPER(km.collection) AS Collection ,\'New API\' AS Type from `MapleMonk.swiggy_campaign_x_report` s LEFT JOIN MapleMonk.Zouk_Quick_Commerce_Ads_mapping km ON LOWER(s.Campaign_Name) LIKE CONCAT(\'%\', LOWER(km.keyword), \'%\') where METRICS_DATE <> \'\' and upper(CAMPAIGN_NAME) not like \'%BOTD%\' ;",
                    "transaction": true
                }
            ) }}
